protected agedOf(personId: number): Aged {
  return this.agedByPerson().get(personId) ?? NO_AGED;
}

protected overdueOf(personId: number): Overdue {
  return this.overdueByPerson().get(personId) ?? NO_OVERDUE;
}

/** The person's score: their settled figures divided by 100, less 5 for each overdue claim that counts, rounded
 *  half to even to a whole number. Worked in whole cents so the halves are exact. */
protected scoreOf(personId: number): string {
  const scaled = this.splitOf(personId).settled - this.overdueOf(personId).count * 5 * 10_000;
  const floor = Math.floor(scaled / 10_000);
  const rest = scaled - floor * 10_000;
  const score = rest > 5_000 || (rest === 5_000 && floor % 2 !== 0) ? floor + 1 : floor;
  return String(score === 0 ? 0 : score);
}

protected snapshotsOf(personId: number): SnapshotView[] {
  return this.snapshots().get(personId) ?? NO_SNAPSHOTS;
}

protected statementOf(personId: number): StatementSummary | undefined {
  return this.statements().get(personId);

